      supabase.from("contribution_cycles").select("id, week_start_date, week_end_date, closes_on, deadline, is_closed").eq("is_closed", false).order("week_start_date", { ascending: false }).limit(1).maybeSingle(),
      supabase.from("contribution_settings").select(
        "weekly_subscription_amount, joining_fee_amount, late_fine_amount, cash_atm_fee_amount"
      ).limit(1).maybeSingle()
